'use strict';
function invitationPage(){const a=current();if(!a)return contextsPage();let block=M.scenario==='wrong'?'wrong':a.invite==='expired'||M.scenario==='expired'?'expired':a.invite==='revoked'||M.scenario==='revoked'?'revoked':'';return head(t('invitation'),a.name,'','S02 · J03-A01 / J03-A02 · AO-005–008')+`<div class="form-panel">${errorBox()}<div class="work-card">${property(t('academy'),esc(a.name))}${property(t('role'),t('owner'))}${property(t('recipient'),`<bdi dir="ltr">${esc(block?'reviewer@example.invalid':a.email)}</bdi>`)}${property(t('scope'),t('setupOnly'))}${property(t('invitation'),t('expiry'))}</div>${block?notice(t('restricted'),esc(t(block)),'error')+(block==='wrong'?btn(t('switch'),'correct-identity','primary'):btn(t('backQueue'),'platform')):a.owner==='accepted'?notice(t('saved'),esc(t('initialOwner')),'success')+btn(t('contexts'),'nav:contexts','primary'):`${notice(t('recipient'),esc(t('verified')))}${notice(t('consequence'),esc(t('initial')+' '+t('initialOwner')),'warn')}<label class="checkline"><input id="accept-confirm" type="checkbox">${t('confirmation')}</label><div class="section">${btn(t('accept'),'accept','primary')}</div>`}</div>`}
function contextsPage(){const a=current();const available=M.academies.filter(x=>x.owner==='accepted');return head(t('contexts'),t('noMembershipCopy'),'','S03 · J01-A01 · AO-002–004/009')+(available.length?`<div class="form-panel">${available.map(x=>`<button class="choice" data-action="choose:${x.id}"><span class="crest">${icon('academy')}</span><span><b>${esc(x.name)}</b><small>${t('owner')} · ${t('setupOnly')}</small><small><bdi dir="ltr">${x.id}</bdi></small></span>${icon('arrow')}</button>`).join('')}${notice(t('scope'),esc(t('initial')))}</div>`:`<div class="empty">${icon('person')}<h2>${t('noMembership')}</h2><p>${t('noMembershipCopy')}</p>${a?btn(t('acceptReview'),'nav:invitation','primary'):''}</div>`)}
function setupPage(){const a=current();if(!permitted())return deniedPage();const done=[!!a.branch,!!a.sportEn,a.complete].filter(Boolean).length;return head(t('setup'),a.name,'','S13 · J04 · AO-011/019')+`<div class="form-panel">${badge(t(a.complete?'complete':'setupOnly'),a.complete?'success':'warn')}${notice(t('scope'),esc(t('initial')))}<div class="work-card"><div class="section-title"><h3>${t('home')}</h3><small class="muted">${done} / 3</small></div><div class="progress-track">${[0,1,2].map(i=>`<i class="${i>=done?'empty':''}"></i>`).join('')}</div>${[['branch',!!a.branch,a.branch?`${a.branch} · ${a.timezone}`:t('branchName')],['sport',!!a.sportEn,a.sportEn?`${a.sportEn} / ${a.sportAr}`:t('sportEn')],['review',a.complete,t('initial')]].map(([p,ok,desc],i)=>`<div class="task-row"><span class="task-num ${ok?'done':''}">${ok?icon('check'):i+1}</span><div class="task-info"><b>${t(p)}</b><p><bdi dir="auto">${esc(desc)}</bdi></p></div>${btn(t(a.complete?'details':ok?'review':'open'),'nav:'+p,'small',a.complete&&p!=='review'?'disabled':'')}</div>`).join('')}</div>${a.complete?notice(t('complete'),esc(t('noActivation')),'success'):''}<p class="draft-note">${t('resume')}</p></div>`}
function setupForm(step){if(!permitted())return deniedPage();const a=current(),d=M.draft;return head(t(step),a.name,'',step==='branch'?'S15 / S14 · J04-A01 · AO-011/019':'S15 · J04-A02 · AO-012/019')+`<div class="form-panel">${steps(step)}${errorBox()}<form id="setup-form" novalidate><div class="work-card form-grid">${step==='branch'?field('branch-name',t('branchName'),d.branch??a.branch)+`<label class="field" for="timezone">${t('timezone')}<select id="timezone" required><option value="">— ${t('choose')} —</option>${['Africa/Cairo','Asia/Riyadh','Asia/Dubai','Europe/London','UTC'].map(z=>`<option value="${z}" ${(d.timezone??a.timezone)===z?'selected':''}>${z}</option>`).join('')}</select><small>${M.lang==='ar'?'اختر صراحةً. القائمة المختصرة توضيحية.':'Choose explicitly. This is an illustrative subset of IANA zones.'}</small></label>`:field('sport-en',t('sportEn'),d.sportEn??a.sportEn,'text','','ltr')+field('sport-ar',t('sportAr'),d.sportAr??a.sportAr,'text','','rtl')}</div><p class="draft-note">${t(M.dirty?'draft':'resume')}</p>${footer('save:'+step,'save')}</form></div>`}
function reviewSetup(){if(!permitted())return deniedPage();const a=current();return head(t('review'),a.name,'','S13 / S15 · J04-A03 · AO-011/019')+`<div class="form-panel">${steps('review')}${errorBox()}<div class="work-card">${property(t('academy'),esc(a.name))}${property(t('branchName'),esc(a.branch||'—'))}${property(t('time'),`<bdi dir="ltr">${esc(a.timezone||'—')}</bdi>`)}${property(t('sportEn'),esc(a.sportEn||'—'))}${property(t('sportAr'),`<bdi dir="rtl">${esc(a.sportAr||'—')}</bdi>`)}</div>${notice(t('consequence'),esc(t('setupReview')+' '+t('initial')),'warn')}${a.complete?notice(t('complete'),esc(t('setupSaved')+' '+t('noActivation')),'success'):`<label class="checkline"><input id="setup-confirm" type="checkbox">${t('confirmation')}</label>`}${a.complete?btn(t('home'),'nav:setup','primary'):footer('complete','finish')}</div>`}
function deniedPage(){return head(t('restricted'),t('readOnly'),'','M1 current-authority boundary')+`<div class="state-card work-card"><h2>${t('restricted')}</h2><p>${t('ownerBoundary')}</p><div class="actions">${btn(t('contexts'),'nav:contexts','primary')}${btn(t('backQueue'),'platform')}</div></div>`}
function scenarioPage(){let s=M.scenario;if(s==='happy'||['failed-delivery','unknown-delivery','wrong','expired','revoked','stale'].includes(s))return null;if(s==='restricted')return deniedPage();if(s==='no-membership')return head(t('contexts'),t('noMembershipCopy'))+`<div class="empty"><h2>${t('noMembership')}</h2><p>${t('noMembershipCopy')}</p>${btn(t('acceptReview'),'recover','primary')}</div>`;if(s==='loading'||s==='saving')return head(t(s==='saving'?'notLive':'loading'),t('notLive'))+`<div class="state-card work-card" aria-busy="true"><h2>${t('loading')}</h2><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><div class="section">${btn(t('next'),'recover','primary')}</div>`;if(s==='unknown')return head(t('unknown'),t('reconcile'))+`<div class="state-card work-card">${notice(t('unknown'),esc(t('reconcile')),'warn')}${property(t('operation'),`<bdi>${esc(M.unknown?.ref||'SIM-ORIGINAL-01')}</bdi>`)}<div class="actions">${btn(t('check'),'reconcile','primary')}</div></div>`;return head(t('recovery'),t('failedRead'))+`<div class="state-card work-card">${notice(t('recovery'),esc(t('failedRead')),'error')}${btn(t('retry'),'recover','primary')}</div>`}
